{
  "root_node": "model.fct_orders",
  "cause": "code_change",
  "action": "patch",
  "evidence": "fct_orders.region_name is sourced from dim_customers via a left join on o.order_key = c.customer_key. dim_customers has no null region_name, but the join condition mismatches keys (order_key vs customer_key), causing 14,625 of 15,000 rows to have no matching customer and thus null region_name. Correcting the join to o.customer_key = c.customer_key will eliminate the nulls."
}
